export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:15。保全室。不是會議室。比會議室小。牆上沒有窗。三面螢幕。中間那面掛著 Patient-Root Location Index 的終端。左邊是 C2 外圍的即時影像。右邊是家屬通知室的待機畫面。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在終端前面。日下部在她左側。司法保全在門邊。外部醫師坐在末端。獨立系統安全人員站在螢幕旁邊。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:20。新的醫療／司法命令送達。不是日下部申請的。是法院在 R5 患者安全程序啟動後自動核發的。命令的標頭只有一行。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "PATIENT-ROOT LOCATION INDEX — AUTHORIZED。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）位置索引。之前的依存圖只能開示管理碼、年齡帶、依存級別。它不能顯示姓名。不能顯示精確位置。不能顯示法人。現在——R5 需要患者綁定本地臨床根。需要當地臨床保管方。需要現場控制器。新的患者安全需要，解鎖了新的資料層。不是從同一張表多看一眼。是——新的命令開了新的門。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:25。獨立系統安全人員在終端上輸入命令編號。螢幕開始載入。進度條走了很久。像在從很深的地方拉東西上來。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後——第一行出現了。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "```text SUBJECT           G07／08 NAME              水瀨 葵 AGE               14 TYPE              HUMAN／MINOR STATUS            ACTIVE／SYSTEM-REPORTED LOCATION          TSUKUBA-AFFILIATE／C2 CLINICAL ISOLATION LOCAL ROOT        NONE CONFIRMED LEGAL STATUS      RESEARCH-ASSIST／SEALED ```", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著那行字。水瀨葵。十四歲。HUMAN。MINOR。ACTIVE。SYSTEM-REPORTED。C2 臨床隔離棟。本地根未確認。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）葵。找到了。不是猜測。不是中等證據強度。是——位置索引正式確認了 mapping。G07／08 等於水瀨葵。她仍在系統裡。她仍在活動。她——仍活著？", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有說話。她看著 ACTIVE／SYSTEM-REPORTED。那是系統宣稱的。不是醫療確認的。LOCAL ROOT — NONE CONFIRMED。本地根未確認。LEGAL STATUS — RESEARCH-ASSIST／SEALED。法定狀態被封緘。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不能只靠系統索引就通知佳乃。系統說她 ACTIVE。系統也說過悠真「自行離家」。系統說過美空「已尋獲」。系統說過紗英「多年前病逝」。系統說的話——不能單獨當作生命確認。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:30。日下部看了一眼螢幕。他的表情沒有變。但他站直了一點。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "位置索引只是第一條。在通知家屬以前——需要第二條。不隸屬 C2 管理鏈的外部醫療。即時生命體徵。現場時間戳。床號與患者識別交叉。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著外部醫師。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "外部醫療。獨立通道。不經 C2 內部系統。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "確認。外部醫療團隊已在 C2 外圍待命。獨立設備。獨立通道。不使用設施內部監測。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:35。外部醫師拿起通訊器。他對 C2 外圍的外部醫療團隊下達指令。聲音很簡潔。像在讀清單。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "獨立生命體徵確認。目標——G07／08。要求——心率、呼吸、基礎腦電。獨立設備讀取。不接觸設施內部系統。現場時間戳。床號與患者識別交叉。回報——即時。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "通訊器裡傳來回覆。很短。確認。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:40。保全室裡安靜了。每個人都在等。螢幕上的 C2 外圍影像沒有變化。灰色的建築。外圍的車道。沒有人進出。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）等。等外部醫療進去。等他們用獨立設備讀到葵的心率。等他們確認——不是系統宣稱的活動。是——一個十四歲的女孩仍有呼吸。仍有心跳。仍有腦電。仍活著。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:55。通訊器響了。外部醫師接起來。他聽了很久。他的表情沒有變。但他的手——拿著筆的手——停了一下。然後繼續寫。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他掛掉通訊器。他看著日下部。他看著澪。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "外部醫療確認。獨立設備讀取。心率——在線。呼吸——在線。基礎腦電——在線。現場時間戳已記錄。床號與患者識別交叉——一致。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "生命體徵——獨立確認。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "```text INDEPENDENT VITAL CONFIRMATION   YES CONFIRMED BY                     EXTERNAL MEDICAL／TIMESTAMPED PATIENT MOVEMENT                 NOT OBSERVED ```", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "保全室裡沒有人說話。螢幕上的字還在那裡。YES。EXTERNAL MEDICAL。TIMESTAMPED。NOT OBSERVED。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她活著。不是系統說的。是外部醫師用獨立設備讀到的。心率在線。呼吸在線。腦電在線。她活著。她在 C2。她沒有被移動。四十二天。四十二天——她一直在那裡。在系統裡。在隔離棟裡。活著。沒有人告訴佳乃。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:05。日下部先動。他走到終端前。他的聲音很平。像在讀程序。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "位置與生命體徵雙重確認。立即執行保全。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著司法保全。司法保全在門邊記錄。每一項。時間戳。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第一——禁止轉移患者。no-move。通知 C2 管理方及外圍警方。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "司法保全記錄。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第二——禁止遠端設定變更。no-config-change。通知獨立系統安全人員監控。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "獨立系統安全人員點頭。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "確認。控制器日誌——保全。禁止銷毀或更換。遠端設定變更——監控中。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第三——當地警方、兒少保護及外部醫療抵達 C2 外圍。建立安全周界。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著通訊器。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第四——救護車及運送車輛監控。出入口保全。任何人不得在未經外部醫療及司法保全同意下移動患者。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:10。指令逐項發出。逐項記錄。逐項回執。C2 外圍的螢幕上開始出現活動。警車。兒少保護的車輛。外部醫療的車輛。他們在外圍停了下來。沒有進入。建立周界。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）no-move。no-config-change。日誌保全。外圍保全。救護車監控。全部生效。可是——沒有進場。C2 是另一個法人管理的設施。進場需要正式程序。今天——只到外圍。進場——明天。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:20。獨立系統安全人員在終端上操作。另一列資料載入。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "```text SUBJECT           LEGACY／02 TYPE              HUMAN／ADULT LOCATION          HAKODATE-AFFILIATE LONG-TERM CARE NODE STATUS            ACTIVE／HIGH DEPENDENCY LOCAL CONTROLLER  LEGACY HARDWARE PATIENT ROOT      UNSUPPORTED／ADAPTER REQUIRED ```", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "LEGACY／02。HUMAN。ADULT。函館節點。舊硬體。患者根不支援。需要轉接器。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "身分依法遮蔽。有法院指定代理。是函館早期暴露者之一。不是設備。舊控制器沒有 Domain-C。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）函館。十年前。夜潮事件。早期暴露者。活人。高依存。舊硬體。沒有 Domain-C。需要轉接器。不是今天能解決的。可是——他不是設備。他是人。他仍在那裡。仍在活動。仍需要被找到。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:30。日下部把 LEGACY／02 的資料封進另一個文件夾。他看了一眼澪。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "函館線——平行進度。不另開主線。外部醫療已派往現場。轉接器規格——設計階段。本章不完成。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯嗯。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:35。保全室裡安靜了一陣。所有指令已經發出。所有回執已經收到。C2 外圍的周界建立了。接下來——通知。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部看著右邊的螢幕。家屬通知室的待機畫面。空的。椅子。桌子。沒有人。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "通知水瀨佳乃。最低必要。不由澪單獨進行。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著在場的人。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "兒少保護。外部醫療。司法保全。家屬支援人員。共同通知。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:40。兒少專業人員從另一個房間進入保全室。她的表情很平。溫和但堅定。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.ChildWelfareOfficer, character: "兒少專業人員", dialogue: "確認。未成年人家屬通知。由兒少保護陪同。確保通知方式不造成二次傷害。不使用引導詞。不承諾無法保證的事項。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師站起來。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "外部醫療在場。負責說明生命體徵確認的醫療部分。不超出醫療判斷範圍。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "司法保全在門邊記錄。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.JudicialPreservation, character: "司法保全", dialogue: "司法保全在場。全程記錄。時間戳。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:45。家屬支援人員到位。不是第七曙光成員。是正式的家屬支援程序人員。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部看著澪。", background: Background.Chapter_24_Ch24_Act4_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "妳可以在保全室看通知室的影像。不進去。不開口。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯我知道。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不能由我通知。不能由我打電話。不能由我說「葵還活著」。因為——如果是我說的，佳乃會先懷疑。她會想：這是不是另一個利用她的人。另一個拿她女兒的名字換東西的人。通知必須由正式程序的人做。由兒少保護。由外部醫療。由司法保全。由家屬支援。不是我。", background: Background.Chapter_24_Ch24_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:00。右邊的螢幕亮了。家屬通知室。門開了。水瀨佳乃走進來。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看起來比上次見到時更瘦。頭髮紮在後面。但很鬆。像沒有力氣紮緊。她的眼睛——很疲憊。但很警覺。她掃了一眼房間裡的人。四個人。沒有澪。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她在找人。她在找熟悉的人。她在找——她能信任的人。她沒有看到我。她看到的是四個陌生人。穿制服的。穿白袍的。穿西裝的。她的戒心——升起來了。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "兒少專業人員先開口。她的聲音很溫和。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ChildWelfareOfficer, character: "兒少專業人員", dialogue: "水瀨女士。請坐。我們有關於您女兒的消息。需要一些時間說明。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃沒有立刻坐下。她站在門邊。她的手握著包的帶子。很緊。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.MinaseYoshino, character: "水瀨佳乃", dialogue: "什麼樣的消息。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.MinaseYoshino_Guarded },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師站起來。他的聲音很穩。臨床。不帶情緒。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "系統索引顯示一名與葵資料一致的患者位於 C2 臨床隔離設施。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃的表情沒有變。她的手——握著帶子的手——收緊了。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "我們也已經從外部取得她目前仍有生命體徵的獨立確認。不經設施內部系統。獨立設備。獨立通道。心率、呼吸、基礎腦電——均在線。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "司法保全在旁邊記錄。每一句。時間戳。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.JudicialPreservation, character: "司法保全", dialogue: "禁止轉移與設定變更已經生效。現場外圍保全已建立。警方、兒少保護及外部醫療已在 C2 外圍。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃還站著。她的嘴唇動了一下。沒有發出聲音。然後——", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ChildWelfareOfficer, character: "兒少專業人員", dialogue: "我們尚未完成現場接管。也不能承諾她現在能安全移動。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃坐下了。不是主動坐下。是——膝蓋軟了。她坐在椅子上。她的手還握著包的帶子。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "很長的沉默。空調的聲音填進房間。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後她抬起頭。她的眼睛——不是感激。不是釋然。是——一個已經被騙過太多次的人，在聽到「找到了」三個字時的第一反應。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.MinaseYoshino, character: "水瀨佳乃", dialogue: "你們找到的是她，還是又一個編號？", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.MinaseYoshino_Guarded },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "保全室裡。澪看著螢幕。她的手指碰著桌面的邊緣。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她問了。她問的是——你們找到的是她，還是又一個編號。不是「她在哪裡」。不是「她好嗎」。是——你們找到的是她，還是編號。因為——四十二天。四十二天裡，她聽過太多「找到了」。太多「有消息了」。太多人拿編號來找她。拿她的女兒的名字換流量。換關注。換點擊。她已經學會了——先問：是編號，還是人。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "通知室裡。兒少專業人員看了一眼外部醫師。外部醫師看了一眼司法保全。然後——兒少專業人員回覆。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ChildWelfareOfficer, character: "兒少專業人員", dialogue: "我們先用編號找到她。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ChildWelfareOfficer, character: "兒少專業人員", dialogue: "現在也有外部醫療確認她仍有生命體徵。接下來要讓醫療和法律程序真正接管她。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃沒有點頭。她沒有說謝謝。她沒有哭。她只是——看著對面的人。看了很久。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她不信任。她不會因為一句「仍有生命體徵」就信任。她等了四十二天。她被警察說過「自行離家」。被學校說過「青春期」。被研究單位說過「睡眠品質低下」。她不會因為四個陌生人坐在她面前說「找到了」就——鬆開手。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:10。佳乃開口了。她的聲音很平。不是冷漠。是——已經把情緒磨平了。像砂紙磨過太多遍的木頭。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.MinaseYoshino, character: "水瀨佳乃", dialogue: "她能聽見嗎。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.MinaseYoshino_Guarded },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "沒有人回答。外部醫師看著監測數據的摘要。他沉默了幾秒。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "⋯⋯我們目前只有獨立生命體徵確認。心率。呼吸。基礎腦電。沒有意識層級評估。沒有聽覺反應測試。尚未進入她的房間。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃沒有追問。她問下一個。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.MinaseYoshino, character: "水瀨佳乃", dialogue: "有人在她身邊嗎。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.MinaseYoshino_Guarded },
    { characterId: CharacterId.ChildWelfareOfficer, character: "兒少專業人員", dialogue: "⋯⋯外部醫療團隊在外圍。尚未進入。C2 內部情況——我們沒有當輪獨立資訊。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃的手指在包的帶子上鬆開了一點。不是放鬆。是——她已經知道答案了。她已經知道沒有人在她女兒身邊。她只是——需要聽別人說出來。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.MinaseYoshino, character: "水瀨佳乃", dialogue: "四十二天。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.MinaseYoshino_Sad },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她停了一下。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.MinaseYoshino, character: "水瀨佳乃", dialogue: "為什麼四十二天沒通知我們。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.MinaseYoshino_Sad },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "司法保全看了一眼兒少專業人員。兒少專業人員沒有回答。因為——沒有答案。或者——有答案，但不是今天能給的。C2 的法定狀態是 RESEARCH-ASSIST／SEALED。研究協助。封緘。這不是一個能被一句話解釋的東西。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "很長的沉默。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ChildWelfareOfficer, character: "兒少專業人員", dialogue: "⋯⋯這個問題我們記錄下來。它需要正式調查。今天——我無法給您答案。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃點了一下頭。很慢。像她早就知道不會有答案。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.MinaseYoshino, character: "水瀨佳乃", dialogue: "我什麼時候能見她。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.MinaseYoshino_Sad },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師和兒少專業人員對視了一眼。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "現場接管尚未完成。進入 C2 需要正式程序。我們會盡快推動。但——我不能承諾時間。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃低下頭。她的頭髮從鬆掉的髮帶裡垂下來。遮住了她的臉。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有再問。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:15。家屬支援人員遞給她一杯水。她接過來。沒有喝。她握著杯子。杯壁上開始凝水珠。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:20。兒少專業人員輕聲說。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.ChildWelfareOfficer, character: "兒少專業人員", dialogue: "水瀨女士。您是葵的患者代理程序核心。後續所有程序——需要您的參與。我們會在每一步之前通知您。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佳乃抬起頭。她的眼睛紅了。但沒有眼淚。她看著兒少專業人員。看了很久。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.MinaseYoshino, character: "水瀨佳乃", dialogue: "⋯⋯好。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.MinaseYoshino_Guarded },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "不是信任。是——她還在等。她還在確認。她還沒有決定這些人是不是值得她把力氣交出來。但她說了「好」。因為——她等了四十二天。她不會放過任何一條可能的路。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:25。通知室的人開始收拾。佳乃還坐著。她握著那杯沒喝的水。她的女兒——在系統裡有了一個位置。在 C2 外圍有了周界。在獨立設備上有了心跳。但——她還沒有見到她。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "保全室裡。澪看著螢幕。螢幕上的佳乃——很瘦。很疲憊。很警覺。像一匹被關太久的動物，聽到門鎖響了，但還不敢走出去。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她問的四個問題。葵能否聽見。有沒有人在她身邊。為什麼四十二天沒有通知。什麼時候能見她。四個問題。沒有一個有答案。今天——沒有。今天只做到了一件事。確認她活著。確認她不會被移走。確認她的位置被鎖住了。可是——她還在隔離棟裡。她還沒有被接管。她還不知道有人在找她。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她閉了一下眼睛。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）找到位置不等於帶她回來。確認生命不等於救出。no-move 不等於自由。今天——只做到了最低必要。可是——最低必要第一次是真的。不是系統宣稱。不是中等證據。是——外部醫療獨立確認。司法保全記錄。兒少保護在場。家屬通知完成。四十二天以來——第一次有人用程序而不是猜測告訴佳乃：你的女兒仍在系統裡。仍有生命體徵。已被鎖住位置。不會被移走。", background: Background.Chapter_24_Ch24_Act4_S1, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她睜開眼睛。螢幕上的通知室空了。佳乃已經走了。杯子留在桌上。水沒有喝。", background: Background.Chapter_24_Ch24_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約一日十七小時三十八分鐘。", background: Background.Chapter_24_Ch24_Act4_S1 },
];
